var n=`1350-locro-de-papa`;var o=`world-1350`;var t=`EC`;var a=`south-america`;var s=4;var r=51;var m={en:`Locro de Papa`,ua:`Локро де папа`};var l={en:`Locro de Papa is a dish from Ecuador featuring yellow onion, garlic, potato, whole cow milk. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Локро де папа, страва кухні країни Еквадор з такими основними складниками: жовта цибуля, часник, картопля, цільне коров'яче молоко. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,160,`g`],[`garlic`,4,`clove`],[`unsalted-butter`,55,`g`]]},{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 28 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 28 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:28,i:[[`potato`,720,`g`],[`chicken-stock`,980,`ml`],[`ground-cumin`,5,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`whole-cow-milk`,380,`ml`],[`queso-fresco`,260,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`avocado`,2,`pcs`],[`cilantro`,25,`g`]]}];var g={slug:n,id:o,country:`EC`,region:a,servings:4,minutes:51,title:m,text:l,steps:d};export{t as country,g as default,o as id,r as minutes,a as region,s as servings,n as slug,d as steps,l as text,m as title};